local env=type(getgenv)=="function"and getgenv()or _G
if env.DevilDumpUnpacking or env.DevilDumpStarting or env.DevilDumpRunning then return end
assert(not env.ValenStandaloneRunning,"Rejoin before switching from ValenHub.")
assert(not env.DevilDumpRequiresRejoin,"Rejoin to reset another active remote hook.")
local loading=DumpLoading.Begin()loading.Busy=true loading.PayloadRunning=true
env.DevilDumpLastError=nil
env.DevilDumpUnpacking=true
local args=table.pack(...)
local ok,result=xpcall(function()
loading:SetStage("Preparing DEVIL DUMP...",.1)
